// Data Validator Pattern
// Validate input data trước khi xử lý

const input = $input.first().json;
const data = input.data || input;
const requiredFields = input.requiredFields || ['email', 'name'];
const rules = input.rules || {};

const errors = [];
const warnings = [];

// 1. Check required fields
const missingFields = requiredFields.filter(field => {
  const value = data[field];
  return value === undefined || value === null || value === '';
});

if (missingFields.length > 0) {
  errors.push(`Missing required fields: ${missingFields.join(', ')}`);
}

// 2. Validate email format
if (data.email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(data.email)) {
    errors.push('Invalid email format');
  }
}

// 3. Validate phone number (Vietnamese format)
if (data.phone) {
  const phoneRegex = /^(\+84|0)[0-9]{9,10}$/;
  if (!phoneRegex.test(data.phone.replace(/[\s-]/g, ''))) {
    warnings.push('Phone number may not be in Vietnamese format. Expected: +84XXXXXXXXX or 0XXXXXXXXXX');
  }
}

// 4. Validate date format
if (data.date) {
  const parsedDate = new Date(data.date);
  if (isNaN(parsedDate.getTime())) {
    errors.push('Invalid date format. Expected: YYYY-MM-DD or ISO string');
  }
}

// 5. Check string length limits
if (rules.maxLength) {
  for (const [field, maxLen] of Object.entries(rules.maxLength)) {
    if (data[field] && data[field].length > maxLen) {
      errors.push(`Field '${field}' exceeds max length of ${maxLen}`);
    }
  }
}

// 6. Check numeric ranges
if (rules.range) {
  for (const [field, range] of Object.entries(rules.range)) {
    const value = Number(data[field]);
    if (!isNaN(value) && (value < range.min || value > range.max)) {
      errors.push(`Field '${field}' must be between ${range.min} and ${range.max}`);
    }
  }
}

// 7. Sanitize strings (remove XSS-like patterns)
const sanitized = { ...data };
for (const [key, value] of Object.entries(data)) {
  if (typeof value === 'string') {
    sanitized[key] = value
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/javascript:/gi, '')
      .replace(/on\w+\s*=/gi, '')
      .trim();
  }
}

const isValid = errors.length === 0;

return [{
  json: {
    valid: isValid,
    data: sanitized,
    errors,
    warnings,
    errorCount: errors.length,
    warningCount: warnings.length,
    validatedFields: Object.keys(data),
    timestamp: new Date().toISOString()
  }
}];
